static int hex_digit(char c)
{
    switch (c) {
    case '0' ... '9':
        return 1;
    case 'a' ... 'f':
        return 1;
    case 'A' ... 'F':
        return 1;
    }
    return 0;
}

static int u8_wc_toutf8(char *dest, uint32_t ch)
{
    if (ch < 0x80) {
        dest[0] = (char)ch;
        return 1;
    }
    if (ch < 0x800) {
        dest[0] = (ch>>6) | 0xC0;
        dest[1] = (ch&0x3F) | 0x80;
        return 2;
    }
    if (ch < 0x10000) {
        dest[0] = (ch>>12) | 0xE0;
        dest[1] = ((ch>>6)&0x3F) | 0x80;
        dest[2] = (ch&0x3F) | 0x80;
        return 3;
    }
    if (ch < 0x110000) {
        dest[0] = (ch>>18) | 0xF0;
        dest[1] = ((ch>>12)&0x3F) | 0x80;
        dest[2] = ((ch>>6)&0x3F) | 0x80;
        dest[3] = (ch&0x3F) | 0x80;
        return 4;
    }
    return 0;
}

static int u8_read_escape_sequence(const char *str, size_t size, uint32_t *dest)
{
    uint32_t ch;
    char digs[10];
    int dno = 0, i = 1;

    ch = (uint32_t)str[0];    /* take literal character */
    digs[0] = 0;

    while (i < size) {
        if (str[i] == '\\') {
            i++;
            if (i >= size) {
                break;
            }
            switch (str[i]) {
            case 'n':
                ch = '\n';
                break;
            case 't':
                ch = '\t';
                break;
            case 'r':
                ch = '\r';
                break;
            case 'b':
                ch = '\b';
                break;
            case 'f':
                ch = '\f';
                break;
            case 'v':
                ch = '\v';
                break;
            case 'a':
                ch = '\a';
                break;
            case '\\':
                ch = '\\';
                break;
            case '"':
                ch = '"';
                break;
            case '\'':
                ch = '\'';
                break;
            case '?':
                ch = '?';
                break;
            case 'x':
                while (i < size && hex_digit(str[i]) && dno < 2) {
                    digs[dno++] = str[i++];
                }
                if (dno > 0) {
                    digs[dno] = 0;
                    ch = strtol(digs, NULL, 16);
                }
                break;
            case 'u':
                while (i < size && hex_digit(str[i]) && dno < 4) {
                    digs[dno++] = str[i++];
                }
                if (dno > 0) {
                    digs[dno] = 0;
                    ch = strtol(digs, NULL, 16);
                }
                break;
            case 'U':
                while (i < size && hex_digit(str[i]) && dno < 8) {
                    digs[dno++] = str[i++];
                }
                if (dno > 0) {
                    digs[dno] = 0;
                    ch = strtol(digs, NULL, 16);
                }
                break;
            default:
                ch = (uint32_t)str[i];
                break;
            }
            i++;
            break;
        }
        else {
            i++;
        }
    }

    *dest = ch;
    return i;
}

int flb_unescape_string_utf8(const char *in, size_t sz, char *out)
{
    uint32_t ch;
    char temp[4];
    size_t count_out = 0;
    size_t esc_in;
    size_t esc_out;

    while (sz > 0) {
        if (*in == '\\') {
            esc_in = u8_read_escape_sequence(in, sz, &ch);
            esc_out = u8_wc_toutf8(temp, ch);
            if (esc_out > sz-count_out) {
                flb_error("Crossing over string boundary");
                break;
            }
            memcpy(out, temp, esc_out);
            out += esc_out;
            count_out += esc_out;
            in += esc_in;
            sz -= esc_in;
        }
        else {
            *out++ = *in++;
            count_out++;
            sz--;
        }
    }
    *out = '\0';
    return count_out;
}

